.sl-method-text {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3.5rem, 6vw, 6rem);
}
.sl-method-text h2,
.sl-method-text h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-method-text .sl-text-muted {
    color: var(--smartlearn-text-muted);
}
.sl-method-text .sl-container-boxed {
    max-width: 1240px;
    margin: 0 auto;
    padding-inline: 1.5rem;
}
@media (min-width: 992px) {
    .sl-method-text .sl-container-boxed {
        padding-inline: 2.5rem;
    }
}
.sl-method-text .sl-badge-eyebrow {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
    color: var(--smartlearn-primary);
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.12em;
}
.sl-method-text .sl-method-heading {
    font-size: clamp(2.2rem, 3.6vw, 3.1rem);
    font-weight: 800;
    line-height: 1.16;
    letter-spacing: -0.035em;
    color: var(--smartlearn-text);
}
.sl-method-text .sl-method-lead {
    font-size: 1.125rem;
    line-height: 1.75;
    color: var(--smartlearn-text-muted);
}
.sl-method-text .sl-accordion-btn {
    padding: 1.15rem 1.65rem;
    background-color: transparent;
    border: 1.5px solid color-mix(in srgb, var(--smartlearn-primary) 30%, var(--smartlearn-card-border));
    color: var(--smartlearn-text);
    transition: border-color 0.3s ease, background-color 0.3s ease, transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
    box-shadow: 0 4px 15px color-mix(in srgb, var(--smartlearn-text) 4%, transparent);
}
.sl-method-text .sl-accordion-btn:hover {
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 8%, transparent);
    transform: translateX(4px);
}
[dir="rtl"] .sl-method-text .sl-accordion-btn:hover {
    transform: translateX(-4px);
}
.sl-method-text .sl-accordion-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
.sl-method-text .sl-accordion-title {
    font-size: 0.98rem;
    letter-spacing: 0.06em;
    font-weight: 700;
}
.sl-method-text .sl-accordion-icon {
    width: 42px;
    height: 42px;
    background-color: color-mix(in srgb, var(--smartlearn-text) 12%, transparent);
    color: var(--smartlearn-text);
    transition: background-color 0.3s ease, color 0.3s ease, transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-text .sl-accordion-icon i {
    font-size: 14px;
}
[dir="rtl"] .sl-method-text .sl-accordion-icon i {
    transform: scaleX(-1);
}
.sl-method-text .sl-accordion-item.active .sl-accordion-btn {
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 10%, transparent);
}
.sl-method-text .sl-accordion-item.active .sl-accordion-icon {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
    transform: rotate(90deg);
}
[dir="rtl"] .sl-method-text .sl-accordion-item.active .sl-accordion-icon {
    transform: rotate(-90deg);
}
.sl-method-text .sl-accordion-body-wrapper {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 0.35s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.25s ease;
    opacity: 0;
}
.sl-method-text .sl-accordion-item.active .sl-accordion-body-wrapper {
    grid-template-rows: 1fr;
    opacity: 1;
}
.sl-method-text .sl-accordion-body {
    min-height: 0;
    overflow: hidden;
    padding-block: 1.25rem 0.5rem;
    padding-inline: 1.25rem 1.5rem;
    font-size: 1.05rem;
    line-height: 1.75;
}
.sl-method-text .sl-stats-bar {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 6%, var(--smartlearn-card-bg));
    border-color: var(--smartlearn-card-border);
}
.sl-method-text .sl-ring-container {
    width: 76px;
    height: 76px;
    flex-shrink: 0;
}
.sl-method-text .sl-ring-svg {
    transform: rotate(-90deg);
}
.sl-method-text .sl-ring-bg {
    stroke: color-mix(in srgb, var(--smartlearn-text) 15%, transparent);
}
.sl-method-text .sl-ring-fill {
    stroke-linecap: round;
    transition: stroke-dasharray 1.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-text .sl-ring-blue {
    stroke: var(--smartlearn-primary);
}
.sl-method-text .sl-ring-teal {
    stroke: var(--smartlearn-primary-hover, var(--smartlearn-primary));
}
.sl-method-text .sl-ring-text {
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--smartlearn-text);
}
.sl-method-text .sl-stat-title {
    font-size: 1.18rem;
    line-height: 1.25;
    color: var(--smartlearn-text);
    letter-spacing: -0.01em;
}
@media (prefers-reduced-motion: reduce) {
    .sl-method-text .sl-accordion-btn,
    .sl-method-text .sl-accordion-icon,
    .sl-method-text .sl-accordion-body-wrapper,
    .sl-method-text .sl-ring-fill {
        transition: none;
    }
    .sl-method-text .sl-accordion-btn:hover {
        transform: none;
    }
}

js:
(function() {
    function initMethodText(root) {
        if (root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        root.querySelectorAll('.sl-ring-container').forEach(ring => {
            const label = ring.querySelector('.sl-ring-text');
            const fill = ring.querySelector('.sl-ring-fill');
            if (!label || !fill) return;
            const val = Math.max(0, Math.min(100, parseFloat(label.textContent) || 0));
            fill.setAttribute('stroke-dasharray', val + ', 100');
        });

        const items = Array.from(root.querySelectorAll('.sl-accordion-item'));
        const headers = items.map(it => it.querySelector('.sl-accordion-header')).filter(Boolean);
        const uid = 'sl-mt-' + Math.random().toString(36).slice(2, 8);

        items.forEach((item, idx) => {
            const btn = item.querySelector('.sl-accordion-header');
            const panel = item.querySelector('.sl-accordion-body-wrapper');
            if (!btn || !panel) return;
            const btnId = uid + '-btn-' + idx;
            const panelId = uid + '-panel-' + idx;
            btn.id = btnId;
            btn.setAttribute('aria-controls', panelId);
            panel.id = panelId;
            panel.setAttribute('aria-labelledby', btnId);
            const active = item.classList.contains('active');
            btn.setAttribute('aria-expanded', active ? 'true' : 'false');
            if (active) panel.removeAttribute('hidden');
            else panel.setAttribute('hidden', '');
        });

        function setOpen(targetIndex) {
            items.forEach((item, idx) => {
                const btn = item.querySelector('.sl-accordion-header');
                const panel = item.querySelector('.sl-accordion-body-wrapper');
                const shouldOpen = idx === targetIndex && !item.classList.contains('active');
                item.classList.toggle('active', shouldOpen);
                if (btn) btn.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
                if (panel) {
                    if (shouldOpen) panel.removeAttribute('hidden');
                    else panel.setAttribute('hidden', '');
                }
            });
        }

        headers.forEach((btn, idx) => {
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                setOpen(idx);
            });
            btn.addEventListener('keydown', (e) => {
                let next = -1;
                if (e.key === 'ArrowDown') next = (idx + 1) % headers.length;
                else if (e.key === 'ArrowUp') next = (idx - 1 + headers.length) % headers.length;
                else if (e.key === 'Home') next = 0;
                else if (e.key === 'End') next = headers.length - 1;
                if (next !== -1) {
                    e.preventDefault();
                    headers[next].focus();
                }
            });
        });
    }

    function initAll() {
        document.querySelectorAll('.sl-method-text').forEach(initMethodText);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
